import functools
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature
import inspect

code_original = \"\"\"
class A:
    pass

def original(a: 'A'):
    return a
\"\"\"
globals_original = {}
exec(code_original, globals_original)
original_fn = globals_original['original']

code_wrapper = \"\"\"
import functools
def wrapper(*args, **kwargs):
    return original(*args, **kwargs)
\"\"\"
globals_wrapper = {'original': original_fn, 'functools': functools}
exec(code_wrapper, globals_wrapper)
wrapper_fn = globals_wrapper['wrapper']

functools.update_wrapper(wrapper_fn, original_fn)

try:
    sig = get_typed_signature(wrapper_fn)
    print(f'Resolved annotation: {sig.parameters[\'a\'].annotation}')
except NameError as e:
    print(f'Caught expected NameError: {e}')
except Exception as e:
    print(f'Caught unexpected exception: {type(e).__name__}: {e}')
